    try (var parser = lines.getFactory().createParser(envelope)) {
        while (parser.nextToken() != null) {
            if (!"summary".equals(parser.currentName())) continue;
            parser.nextToken();
            return decodeSummary(lines.readTree(parser));
        }
    }
    throw new IllegalStateException("JSONL Session summary is missing");
}

